using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using MindCare.Data;using MindCare.Models;
namespace MindCare.Controllers;
[Authorize(Roles=RoleNames.Admin)] public class AdminResourceCategoriesController(ApplicationDbContext context):Controller
{ public async Task<IActionResult> Index()=>View(await context.ResourceCategories.OrderBy(c=>c.Name).ToListAsync()); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Save(int? id,string name,string? description){name=name?.Trim()??"";if(string.IsNullOrWhiteSpace(name)||await context.ResourceCategories.AnyAsync(c=>c.Name.ToLower()==name.ToLower()&&c.Id!=id)){TempData["ErrorMessage"]="Enter a unique category name.";return RedirectToAction(nameof(Index));}var c=id.HasValue?await context.ResourceCategories.FindAsync(id):new ResourceCategory{CreatedAt=DateTime.UtcNow};if(c is null)return NotFound();c.Name=name;c.Description=description?.Trim();if(!id.HasValue)context.ResourceCategories.Add(c);await context.SaveChangesAsync();return RedirectToAction(nameof(Index));} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Toggle(int id){var c=await context.ResourceCategories.FindAsync(id);if(c is null)return NotFound();c.IsActive=!c.IsActive;await context.SaveChangesAsync();return RedirectToAction(nameof(Index));}}
